1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
3	const BLOCK_SIZE = 3;
4	const BLOCK_BASE_PREMIUM = 60;
5	
6	const BASE_PREMIUMS: Record<string, number> = {
7	  sword: 100,
8	  amulet: 60,
9	  staff: 80,
10	  potion: 40,
11	  rune: 25,
12	};
13	
14	// Divides rather than multiplying by a rate: `amount * 1.1` introduces
15	// floating-point error that shifts the spec's round-up in MHPCO's favour.
16	const percentOf = (percent: number, amount: number): number => (amount * percent) / 100;
17	
18	// MHPCO rounds every money amount in its own favour: premiums (customer pays)
19	// round up, payouts (MHPCO pays) round down.
20	const roundPremiumInMHPCOsFavour = Math.ceil;
21	
22	export type ScenarioResult = { premium: number };
23	
24	type Item = { type: string };
25	
26	type Scenario = {
27	  steps: { items: Item[] }[];
28	};
29	
30	const basePremiumForItem = (item: Item): number => BASE_PREMIUMS[item.type];
31	
32	export const runScenario = (scenario: Scenario): { results: ScenarioResult[] } => {
33	  const [quoteStep] = scenario.steps;
34	  const items = quoteStep.items;
35	  const isBlock = items.length === BLOCK_SIZE && items.every((item) => item.type === "rune");
36	  const policyBasePremium = isBlock
37	    ? BLOCK_BASE_PREMIUM
38	    : items.reduce((total, item) => total + basePremiumForItem(item), 0);
39	  const firstInsuranceSurcharge = percentOf(FIRST_INSURANCE_SURCHARGE_PERCENT, policyBasePremium);
40	  const premium = roundPremiumInMHPCOsFavour(
41	    policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE,
42	  );
43	  return { results: [{ premium }] };
44	};
