const basePremiumForItem = (item: Item): number => BASE_PREMIUMS[item.type];

const sumBasePremiums = (items: Item[]): number =>
  items.reduce((total, item) => total + basePremiumForItem(item), 0);

// Only recognises a block when the ENTIRE item list is one: no test yet covers
// a block alongside other items, so nothing drives grouping by component type.
const itemsFormASingleBlock = (items: Item[]): boolean =>
  items.length === BLOCK_SIZE && items.every((item) => item.type === "rune");

export const runScenario = (scenario: Scenario): { results: ScenarioResult[] } => {
  const [quoteStep] = scenario.steps;
  const items = quoteStep.items;
  const policyBasePremium = itemsFormASingleBlock(items)
    ? BLOCK_BASE_PREMIUM
    : sumBasePremiums(items);
